migrations.sql:
-- Additive schema draft. Integrator assigns the next migration number; never
-- replace an applied migration. All epoch timestamps are milliseconds.
CREATE TABLE oa_operators (
 id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL,
 role TEXT NOT NULL CHECK(role IN ('owner','admin','member')),
 status TEXT NOT NULL CHECK(status IN ('invited','active','inactive')),
 version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, last_signin_at INTEGER
);
CREATE TABLE oa_bootstrap (singleton INTEGER PRIMARY KEY CHECK(singleton=1), claim_id TEXT NOT NULL UNIQUE, claimed_at INTEGER NOT NULL);
CREATE TABLE oa_tokens (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 kind TEXT NOT NULL CHECK(kind IN ('magic','invite')),
 operator_id TEXT NOT NULL REFERENCES oa_operators(id), operator_version INTEGER NOT NULL,
 issuer_id TEXT REFERENCES oa_operators(id), issuer_version INTEGER,
 return_to TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL,
 consumed_at INTEGER, revoked_at INTEGER,
 CHECK((kind='invite' AND issuer_id IS NOT NULL AND issuer_version IS NOT NULL)
    OR (kind='magic' AND issuer_id IS NULL AND issuer_version IS NULL))
);
CREATE TABLE oa_sessions (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 operator_id TEXT NOT NULL REFERENCES oa_operators(id), operator_version INTEGER NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('native','review','oidc','password','dev')),
 source_token_id TEXT UNIQUE REFERENCES oa_tokens(id),
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);
CREATE INDEX oa_sessions_operator ON oa_sessions(operator_id);
-- Admission history survives credential expiry, revocation and portability scrubbing.
-- Existing stores apply schema/last-signin.sql after session rebuild migrations.
CREATE TRIGGER oa_record_last_signin AFTER INSERT ON oa_sessions
 BEGIN UPDATE oa_operators SET last_signin_at=NEW.created_at
 WHERE id=NEW.operator_id AND (last_signin_at IS NULL OR last_signin_at<NEW.created_at); END;
CREATE TABLE oa_external_identities (
 issuer TEXT NOT NULL, subject TEXT NOT NULL, operator_id TEXT NOT NULL REFERENCES oa_operators(id),
 PRIMARY KEY(issuer, subject)
);
CREATE TABLE oa_limits (key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TRIGGER oa_preserve_last_owner_update BEFORE UPDATE OF status,role ON oa_operators
 WHEN OLD.role='owner' AND OLD.status='active' AND (NEW.role!='owner' OR NEW.status!='active')
 AND (SELECT COUNT(*) FROM oa_operators WHERE role='owner' AND status='active') <= 1
 BEGIN SELECT RAISE(ABORT, 'last_owner'); END;
CREATE TRIGGER oa_preserve_last_owner_delete BEFORE DELETE ON oa_operators
 WHEN OLD.role='owner' AND OLD.status='active'
 AND (SELECT COUNT(*) FROM oa_operators WHERE role='owner' AND status='active') <= 1
 BEGIN SELECT RAISE(ABORT, 'last_owner'); END;
-- A status/role change invalidates every preexisting session and link, including
-- after a later reactivation. Keep this invariant for direct administrative SQL.
CREATE TRIGGER oa_operator_version AFTER UPDATE OF status,role ON oa_operators
 WHEN OLD.status != NEW.status OR OLD.role != NEW.role
 BEGIN UPDATE oa_operators SET version=OLD.version+1 WHERE id=NEW.id; END;

-- Fresh installs include local dev identity. Apply schema/dev-sessions.sql as a
-- NEW numbered migration in existing stores; it is also safe after this file.
-- A credential minted while signed in with a dev session is recorded here and,
-- like the dev session itself, counts only behind the local key gate.
CREATE TABLE IF NOT EXISTS oa_dev_credentials (
 credential TEXT NOT NULL, id TEXT NOT NULL, created_at INTEGER NOT NULL,
 PRIMARY KEY(credential, id)
);

-- Fresh installs include the additive invitation cancellation ledger.
-- Apply as a NEW numbered migration after operator-auth.sql in existing stores.
-- This durable record is admission state, not an expiring credential. Never prune it.
-- Existing active/inactive operators retain their recorded status: no historical
-- acceptance is inferred. Only a witnessed invited -> inactive transition records
-- an unaccepted cancellation, including direct administrative SQL transitions.
CREATE TABLE oa_invitation_cancellations (
 operator_id TEXT PRIMARY KEY REFERENCES oa_operators(id),
 operator_version INTEGER NOT NULL
);
CREATE TRIGGER oa_record_invitation_cancellation AFTER UPDATE OF status ON oa_operators
 WHEN OLD.status='invited' AND NEW.status='inactive'
 BEGIN INSERT INTO oa_invitation_cancellations(operator_id,operator_version)
 VALUES(NEW.id,OLD.version+1)
 ON CONFLICT(operator_id) DO UPDATE SET operator_version=excluded.operator_version; END;
CREATE TRIGGER oa_reject_cancelled_invitation_reactivation BEFORE UPDATE OF status ON oa_operators
 WHEN NEW.status='active' AND EXISTS(SELECT 1 FROM oa_invitation_cancellations WHERE operator_id=OLD.id)
 BEGIN SELECT RAISE(ABORT, 'invitation_required'); END;

-- Fresh installs include domain rules and step-up proofs. Apply
-- schema/domain-rules-step-up.sql as a NEW numbered migration in existing
-- stores; it is also safe after this file.
-- A required sign-in provider for an email domain. Sign-ins for that domain by
-- any other route are refused; app owners are exempt.
CREATE TABLE IF NOT EXISTS oa_domain_rules (
 domain TEXT PRIMARY KEY, provider_id TEXT NOT NULL,
 created_by TEXT NOT NULL REFERENCES oa_operators(id), created_at INTEGER NOT NULL
);
-- A step-up proof: an app-local email link sent to the operator's own address,
-- bound to the session that asked and completed only in that session. No
-- foreign key names oa_sessions, which schema/dev-sessions.sql rebuilds.
CREATE TABLE IF NOT EXISTS oa_step_up_challenges (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 session_id TEXT NOT NULL, operator_id TEXT NOT NULL REFERENCES oa_operators(id),
 operator_version INTEGER NOT NULL, action TEXT NOT NULL, return_to TEXT NOT NULL,
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER
);
CREATE INDEX IF NOT EXISTS oa_step_up_session ON oa_step_up_challenges(session_id);

-- Additive provider controls. An absent setting means off, including upgrades.
CREATE TABLE IF NOT EXISTS oa_auth_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), idp_sign_in INTEGER NOT NULL CHECK(idp_sign_in IN (0,1)), generation INTEGER NOT NULL DEFAULT 0, first_setup INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS oa_auth_audit (
 id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, value TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS oa_provider_sessions (
 session_id TEXT PRIMARY KEY, issuer TEXT NOT NULL, subject TEXT NOT NULL, sid TEXT, generation INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS oa_provider_session_identity ON oa_provider_sessions(issuer,subject,sid);
CREATE TABLE IF NOT EXISTS oa_logout_events (
 issuer TEXT NOT NULL, jti TEXT NOT NULL, consumed_at INTEGER NOT NULL CHECK(consumed_at>=0), PRIMARY KEY(issuer,jti)
);

CREATE TRIGGER IF NOT EXISTS oa_first_setup_provider_setting AFTER INSERT ON oa_bootstrap BEGIN
 INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup) VALUES(1,0,0,1) ON CONFLICT DO NOTHING;
END;

CREATE TABLE IF NOT EXISTS oa_credentials (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, operator_id TEXT NOT NULL REFERENCES oa_operators(id),
 operator_version INTEGER, kind TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);

-- Session provenance for OIDC pins. Apply as a new migration on existing stores.
-- External admission has no OIDC pin and does not require OIDC protocol tables.
CREATE TABLE IF NOT EXISTS oa_provider_session_pins (
 session_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, issuer TEXT NOT NULL,
 client_id TEXT NOT NULL, linked_at INTEGER NOT NULL
);

-- Ephemeral app-local setup attempts are never exported. A native claim binds
-- only attempts opened before that claim to its exact owner/session authority,
-- in its own bootstrap transaction.
CREATE TABLE IF NOT EXISTS oa_setup_links (
 interface TEXT PRIMARY KEY, attempt_id TEXT NOT NULL, expires_at INTEGER NOT NULL,
 owner_id TEXT, owner_version INTEGER, session_id TEXT,
 completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0,1))
);
CREATE TRIGGER IF NOT EXISTS oa_native_claim_closes_provider_setup AFTER INSERT ON oa_sessions
WHEN NEW.kind='native' AND NOT EXISTS(SELECT 1 FROM oa_sessions WHERE operator_id=NEW.operator_id AND id!=NEW.id) AND EXISTS(SELECT 1 FROM oa_bootstrap WHERE claim_id=NEW.operator_id AND claimed_at=NEW.created_at)
BEGIN
 UPDATE oa_auth_settings SET first_setup=0 WHERE singleton=1 AND NOT EXISTS(
  SELECT 1 FROM oa_setup_links WHERE interface='oidc-provider@1' AND completed=0 AND owner_id IS NULL AND expires_at>NEW.created_at
 );
 UPDATE oa_setup_links SET owner_id=NEW.operator_id,owner_version=NEW.operator_version,session_id=NEW.id
 WHERE owner_id IS NULL AND completed=0 AND expires_at>NEW.created_at;
END;

-- Apply as a NEW numbered migration. Authority and audit are durable, not sessions.
CREATE TABLE IF NOT EXISTS oa_policy_approvals (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL, version_hash TEXT NOT NULL,
 definition TEXT NOT NULL, actions TEXT NOT NULL,
 owner_id TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL,
 approved_at INTEGER NOT NULL, revoked_at INTEGER,
 session_kind TEXT NOT NULL, revoke_reason TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS oa_policy_live ON oa_policy_approvals(policy_id) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS oa_policy_runs (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL, version_hash TEXT,
 approval_id TEXT REFERENCES oa_policy_approvals(id), approved_by TEXT,
 started_at INTEGER NOT NULL, finished_at INTEGER,
 status TEXT NOT NULL CHECK(status IN ('running','completed','refused','failed')), error TEXT,
 admitted INTEGER NOT NULL DEFAULT 0, repeats INTEGER NOT NULL DEFAULT 1, last_seen_at INTEGER
);
CREATE INDEX IF NOT EXISTS oa_policy_runs_time ON oa_policy_runs(started_at DESC);
CREATE INDEX IF NOT EXISTS oa_policy_action_run ON oa_auth_audit(CASE WHEN json_valid(value) THEN json_extract(value,'$.runId') END,action);

-- Additive local-development storage. Apply explicitly to the local D1 database.
CREATE TABLE IF NOT EXISTS rer_mail_development_outbox (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  message TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS rer_mail_development_outbox_order
  ON rer_mail_development_outbox(created_at DESC, sequence DESC);

CREATE TABLE rer_portability_state (
  id INTEGER PRIMARY KEY CHECK(id=1), source_identity TEXT NOT NULL, epoch INTEGER NOT NULL DEFAULT 0,
  import_job TEXT, applying INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE rer_portability_jobs (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL, actor TEXT NOT NULL, phase TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0, metadata TEXT NOT NULL
);
CREATE TABLE rer_portability_parts (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  idx INTEGER NOT NULL, sha256 TEXT NOT NULL, PRIMARY KEY(job,idx)
);
CREATE TABLE rer_portability_segments (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  part INTEGER NOT NULL, segment INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(job,part,segment)
);
CREATE TABLE rer_portability_owned (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  bucket TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY(job,bucket,key)
);
CREATE TABLE rer_portability_journal (
  source TEXT NOT NULL, tombstone TEXT NOT NULL, PRIMARY KEY(source,tombstone)
);
CREATE TABLE rer_portability_epochs (source TEXT PRIMARY KEY, epoch INTEGER NOT NULL);
CREATE TABLE rer_portability_guard (value INTEGER NOT NULL CHECK(value=1));

-- Additive provider controls. An absent setting means off, including upgrades.
CREATE TABLE IF NOT EXISTS oa_auth_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), idp_sign_in INTEGER NOT NULL CHECK(idp_sign_in IN (0,1)), generation INTEGER NOT NULL DEFAULT 0, first_setup INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS oa_auth_audit (
 id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, value TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS oa_provider_sessions (
 session_id TEXT PRIMARY KEY, issuer TEXT NOT NULL, subject TEXT NOT NULL, sid TEXT, generation INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS oa_provider_session_identity ON oa_provider_sessions(issuer,subject,sid);
CREATE TABLE IF NOT EXISTS oa_logout_events (
 issuer TEXT NOT NULL, jti TEXT NOT NULL, consumed_at INTEGER NOT NULL CHECK(consumed_at>=0), PRIMARY KEY(issuer,jti)
);

CREATE TRIGGER IF NOT EXISTS oa_first_setup_provider_setting AFTER INSERT ON oa_bootstrap BEGIN
 INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup) VALUES(1,0,0,1) ON CONFLICT DO NOTHING;
END;

CREATE TABLE IF NOT EXISTS oa_credentials (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, operator_id TEXT NOT NULL REFERENCES oa_operators(id),
 operator_version INTEGER, kind TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);

-- Session provenance for OIDC pins. Apply as a new migration on existing stores.
-- External admission has no OIDC pin and does not require OIDC protocol tables.
CREATE TABLE IF NOT EXISTS oa_provider_session_pins (
 session_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, issuer TEXT NOT NULL,
 client_id TEXT NOT NULL, linked_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS rer_dependency_installation (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), sector_id TEXT NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS rer_dependency_link (
 interface TEXT PRIMARY KEY, issuer TEXT NOT NULL, client_id TEXT NOT NULL, metadata TEXT NOT NULL,
 needs_relink INTEGER NOT NULL DEFAULT 0, linked_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS rer_dependency_pending (
 interface TEXT PRIMARY KEY, issuer TEXT NOT NULL, approved_by TEXT NOT NULL, expires_at INTEGER NOT NULL, approved_session TEXT NOT NULL, approved_version INTEGER NOT NULL, callbacks TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS rer_dependency_codes (
 digest TEXT PRIMARY KEY, created_at INTEGER NOT NULL CHECK(created_at>=0)
);

CREATE TABLE IF NOT EXISTS rer_dependency_keys (interface TEXT PRIMARY KEY, private_key TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS oc_idp_grants (
 issuer TEXT NOT NULL, client_id TEXT NOT NULL, jti TEXT NOT NULL, subject TEXT NOT NULL, sector_id TEXT NOT NULL,
 PRIMARY KEY(issuer,client_id), UNIQUE(issuer,jti)
);

-- Session provenance for OIDC pins. Apply as a new migration on existing stores.
-- External admission has no OIDC pin and does not require OIDC protocol tables.
CREATE TABLE IF NOT EXISTS oa_provider_session_pins (
 session_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, issuer TEXT NOT NULL,
 client_id TEXT NOT NULL, linked_at INTEGER NOT NULL
);

-- Ephemeral app-local setup attempts are never exported. A native claim binds
-- only attempts opened before that claim to its exact owner/session authority,
-- in its own bootstrap transaction.
CREATE TABLE IF NOT EXISTS oa_setup_links (
 interface TEXT PRIMARY KEY, attempt_id TEXT NOT NULL, expires_at INTEGER NOT NULL,
 owner_id TEXT, owner_version INTEGER, session_id TEXT,
 completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0,1))
);
CREATE TRIGGER IF NOT EXISTS oa_native_claim_closes_provider_setup AFTER INSERT ON oa_sessions
WHEN NEW.kind='native' AND NOT EXISTS(SELECT 1 FROM oa_sessions WHERE operator_id=NEW.operator_id AND id!=NEW.id) AND EXISTS(SELECT 1 FROM oa_bootstrap WHERE claim_id=NEW.operator_id AND claimed_at=NEW.created_at)
BEGIN
 UPDATE oa_auth_settings SET first_setup=0 WHERE singleton=1 AND NOT EXISTS(
  SELECT 1 FROM oa_setup_links WHERE interface='oidc-provider@1' AND completed=0 AND owner_id IS NULL AND expires_at>NEW.created_at
 );
 UPDATE oa_setup_links SET owner_id=NEW.operator_id,owner_version=NEW.operator_version,session_id=NEW.id
 WHERE owner_id IS NULL AND completed=0 AND expires_at>NEW.created_at;
END;

-- Existing pending approvals predate attempt fencing and must be renewed.
ALTER TABLE rer_dependency_pending ADD COLUMN attempt_id TEXT;
DELETE FROM rer_dependency_pending;

-- PEG-001: the persistent work graph. Workspaces, teams, projects, sections, tasks and the one history each task keeps.
-- A task is one row; peg_task_projects is its multi-homing. Operators are Base's people (oa_operators).
CREATE TABLE peg_workspaces (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, settings TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL
);
-- Who belongs to a workspace and as what. Base owners and admins are implicit administrators of every workspace;
-- everyone else needs a row (member, manager, analyst, guest or agent).
CREATE TABLE peg_workspace_members (
  workspace_id TEXT NOT NULL, operator_id TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('manager','member','analyst','guest','agent')),
  created_by TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(workspace_id, operator_id)
);
CREATE TABLE peg_teams (
  id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
  privacy TEXT NOT NULL CHECK(privacy IN ('public','request','private')),
  default_level TEXT NOT NULL DEFAULT 'viewer' CHECK(default_level IN ('viewer','commenter','editor')),
  fallback_id TEXT, policy_rev INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE INDEX peg_teams_workspace ON peg_teams(workspace_id);
CREATE TABLE peg_projects (
  id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
  owner_id TEXT NOT NULL, team_id TEXT,
  visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','team','workspace')),
  team_level TEXT NOT NULL DEFAULT 'viewer' CHECK(team_level IN ('viewer','commenter','editor')),
  workspace_level TEXT NOT NULL DEFAULT 'viewer' CHECK(workspace_level IN ('viewer','commenter','editor')),
  status TEXT NOT NULL DEFAULT 'active', start_date TEXT, due_date TEXT, prefix TEXT,
  policy_rev INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE INDEX peg_projects_workspace ON peg_projects(workspace_id);
-- A section is a project's own column; maps_to ties it to the task's one status (the workflow mapping).
CREATE TABLE peg_sections (
  id TEXT PRIMARY KEY, project_id TEXT NOT NULL, name TEXT NOT NULL, position INTEGER NOT NULL,
  maps_to TEXT CHECK(maps_to IN ('todo','doing','done'))
);
CREATE INDEX peg_sections_project ON peg_sections(project_id, position);
-- A project's field library: values live per task and project, readable by the audience the field names.
CREATE TABLE peg_project_fields (
  project_id TEXT NOT NULL, key TEXT NOT NULL, label TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('text','number')),
  visibility TEXT NOT NULL DEFAULT 'everyone' CHECK(visibility IN ('everyone','internal','editors','admins')),
  PRIMARY KEY(project_id, key)
);
CREATE TABLE peg_tasks (
  id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL DEFAULT 'task' CHECK(kind IN ('task','subtask','milestone')), parent_id TEXT,
  status TEXT NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','doing','done')),
  priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')),
  start_date TEXT, due_date TEXT, owner_id TEXT NOT NULL, creator_id TEXT NOT NULL,
  estimate_hours REAL NOT NULL DEFAULT 0, internal_only INTEGER NOT NULL DEFAULT 0, internal_notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, completed_at INTEGER
);
CREATE INDEX peg_tasks_parent ON peg_tasks(parent_id);
CREATE INDEX peg_tasks_owner ON peg_tasks(owner_id);
CREATE TABLE peg_task_collaborators (task_id TEXT NOT NULL, operator_id TEXT NOT NULL, PRIMARY KEY(task_id, operator_id));
CREATE TABLE peg_task_projects (
  task_id TEXT NOT NULL, project_id TEXT NOT NULL, section_id TEXT, fields TEXT NOT NULL DEFAULT '{}',
  position INTEGER NOT NULL DEFAULT 0, added_by TEXT NOT NULL, added_at INTEGER NOT NULL, PRIMARY KEY(task_id, project_id)
);
CREATE INDEX peg_task_projects_project ON peg_task_projects(project_id, section_id, position);
-- References: every prefix and every reference ever issued stays reserved, so an old one keeps resolving to its task.
CREATE TABLE peg_ref_prefixes (
  prefix TEXT PRIMARY KEY, project_id TEXT NOT NULL, next_number INTEGER NOT NULL DEFAULT 1, retired_to TEXT
);
CREATE TABLE peg_task_refs (
  ref TEXT PRIMARY KEY, task_id TEXT NOT NULL, current INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL
);
CREATE INDEX peg_task_refs_task ON peg_task_refs(task_id);
-- One history per task. project_id names the project an entry belongs to, or null for the task's own shared record.
CREATE TABLE peg_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT, task_id TEXT NOT NULL, project_id TEXT, at INTEGER NOT NULL,
  actor_id TEXT NOT NULL, kind TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX peg_history_task ON peg_history(task_id, id);
CREATE TABLE peg_comments (
  id TEXT PRIMARY KEY, task_id TEXT NOT NULL, project_id TEXT, author_id TEXT NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE INDEX peg_comments_task ON peg_comments(task_id, created_at);
-- Files attach through a project (readable by that project's audience) or, for a personal task, to its owner alone.
CREATE TABLE peg_attachments (
  id TEXT PRIMARY KEY, task_id TEXT NOT NULL, project_id TEXT, name TEXT NOT NULL, content_type TEXT NOT NULL,
  size INTEGER NOT NULL, data BLOB NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE INDEX peg_attachments_task ON peg_attachments(task_id);

-- PEG-020: grants, the access audit and the PEG-083 request lifecycle.
-- A team's membership is a person grant on the team; a project shared with a team is a team grant on the project.
CREATE TABLE peg_grants (
  id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL,
  object_type TEXT NOT NULL CHECK(object_type IN ('team','project','task')), object_id TEXT NOT NULL,
  grantee_type TEXT NOT NULL CHECK(grantee_type IN ('person','team')), grantee_id TEXT NOT NULL,
  level TEXT NOT NULL CHECK(level IN ('viewer','commenter','editor','admin')),
  scope TEXT NOT NULL DEFAULT 'full' CHECK(scope IN ('full','approve','assignee')), scopes TEXT,
  source TEXT NOT NULL CHECK(source IN ('direct','join','request')), request_id TEXT,
  created_by TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER, revoked_at INTEGER, revoked_by TEXT
);
CREATE INDEX peg_grants_object ON peg_grants(object_type, object_id);
CREATE INDEX peg_grants_grantee ON peg_grants(grantee_type, grantee_id);
CREATE TABLE peg_approvers (object_type TEXT NOT NULL, object_id TEXT NOT NULL, operator_id TEXT NOT NULL, PRIMARY KEY(object_type, object_id, operator_id));
-- Every authority change recorded once: who, what, to whom, the levels and the reason.
CREATE TABLE peg_audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT, at INTEGER NOT NULL, actor_id TEXT, action TEXT NOT NULL,
  target_type TEXT, target_id TEXT, subject_id TEXT, detail TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX peg_audit_workspace ON peg_audit(workspace_id, id);
-- Bumped by every authority change; a decision re-reads it inside its own write.
CREATE TABLE peg_epoch (id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL);
INSERT INTO peg_epoch VALUES (1, 1);
CREATE TABLE peg_access_requests (
  id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, requester_id TEXT NOT NULL, requester_version INTEGER NOT NULL,
  target_type TEXT NOT NULL CHECK(target_type IN ('team','project','task')), target_id TEXT NOT NULL,
  level TEXT NOT NULL CHECK(level IN ('viewer','commenter','editor','admin')), message TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL CHECK(status IN ('pending','approved','denied','expired','stale')),
  policy_rev INTEGER NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL,
  decided_by TEXT, decided_at INTEGER, decision_reason TEXT, granted_level TEXT, grant_id TEXT, duplicates INTEGER NOT NULL DEFAULT 0
);
-- One pending request per requester and target, however many submissions race.
CREATE UNIQUE INDEX peg_access_requests_active ON peg_access_requests(requester_id, target_type, target_id) WHERE status='pending';
CREATE INDEX peg_access_requests_target ON peg_access_requests(target_type, target_id);
-- The inbox: a delivery to one person, with the minimum a fallback recipient may know.
CREATE TABLE peg_inbox (
  id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('request','fallback','decision')),
  request_id TEXT NOT NULL, created_at INTEGER NOT NULL, read_at INTEGER
);
CREATE INDEX peg_inbox_operator ON peg_inbox(operator_id, created_at);
CREATE TABLE peg_webhooks (
  id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, project_id TEXT, url TEXT NOT NULL, events TEXT NOT NULL, secret_hash TEXT NOT NULL,
  created_by TEXT NOT NULL, created_at INTEGER NOT NULL, revoked_at INTEGER
);

-- Personal layout belongs to the person, never to a project.
CREATE TABLE peg_personal_settings (operator_id TEXT PRIMARY KEY, timezone TEXT NOT NULL DEFAULT 'America/New_York', sort TEXT NOT NULL DEFAULT 'default' CHECK(sort IN ('default','manual')));
CREATE TABLE peg_personal_sections (id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, name TEXT NOT NULL, position REAL NOT NULL);
CREATE TABLE peg_personal_layout (operator_id TEXT NOT NULL, task_id TEXT NOT NULL, section_id TEXT, position REAL NOT NULL DEFAULT 0, today INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(operator_id,task_id));
CREATE TABLE peg_personal_rules (id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, group_name TEXT NOT NULL CHECK(group_name IN ('Overdue','Today','Upcoming','Later')), section_id TEXT NOT NULL);
CREATE TABLE peg_personal_moves (id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, task_id TEXT NOT NULL, rule_id TEXT NOT NULL, local_day TEXT NOT NULL, before_section TEXT, after_section TEXT NOT NULL, before_position REAL NOT NULL, undone INTEGER NOT NULL DEFAULT 0, UNIQUE(operator_id,task_id,rule_id,local_day));
CREATE TABLE peg_personal_revision (id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL);
INSERT INTO peg_personal_revision VALUES(1,1);
CREATE TABLE peg_personal_guards (id TEXT PRIMARY KEY, revision INTEGER NOT NULL);
CREATE TRIGGER peg_personal_guard BEFORE INSERT ON peg_personal_guards BEGIN
 SELECT CASE WHEN NEW.revision<>(SELECT value FROM peg_personal_revision WHERE id=1) THEN RAISE(ABORT,'stale_personal_preview') END;
END;
CREATE TRIGGER peg_personal_rev_peg_tasks_insert AFTER INSERT ON peg_tasks BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_personal_rev_peg_tasks_update AFTER UPDATE ON peg_tasks BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
