BEGIN DELETE FROM peg_bulk_effects WHERE task_id=NEW.object_id; END;
CREATE TRIGGER peg_bulk_task_deleted AFTER DELETE ON peg_tasks BEGIN DELETE FROM peg_bulk_effects WHERE task_id=OLD.id; END;
